    <div class="dashboard-layout"><main class="schedule-main"><q-card flat class="control-card"><q-card-section class="controls"><q-input v-model="search" dense outlined clearable debounce="150" placeholder="Buscar assunto..." aria-label="Buscar assunto"><template #prepend><q-icon name="search" /></template></q-input><q-select v-model="statusFilter" dense outlined emit-value map-options label="Situação" :options="statusFilters"/><q-btn outline no-caps color="primary" label="Expandir todos" @click="expandAll"/><q-btn outline no-caps color="primary" label="Recolher todos" @click="collapseAll"/><div class="view-controls"><span>Vista:</span><q-btn-toggle v-model="view" dense no-caps unelevated toggle-color="primary" :options="[{label:'Semanal',value:'week'},{label:'Diária',value:'day'},{label:'Mensal',value:'month'}]"/></div></q-card-section></q-card>
      <q-card flat class="gantt-card"><q-card-section class="gantt-scroll"><div class="gantt-map" aria-label="Mapa de estudo SVG">
        <div class="labels-header"><svg :width="labelWidth" :height="headerHeight"><rect width="100%" height="100%" fill="#f4f8fd"/><text x="14" y="27" class="heading">Assunto / Subassunto</text><text x="252" y="27" class="heading">Estimativa</text><text x="334" y="27" class="heading">Progresso</text></svg></div>
        <div ref="timelineHeader" class="timeline-header" aria-label="Cabeçalho do período" @scroll="syncHeader"><svg :width="timelineWidth" :height="headerHeight"><rect width="100%" height="100%" fill="#f4f8fd"/><g v-for="(period,index) in timeline" :key="period"><line :x1="index*periodWidth" y1="0" :x2="index*periodWidth" :y2="headerHeight" class="grid"/><text :x="index*periodWidth+periodWidth/2" y="27" text-anchor="middle" class="heading">{{ timelineLabel(period) }}</text></g><line :x1="timelineWidth" y1="0" :x2="timelineWidth" :y2="headerHeight" class="grid"/></svg></div>
        <div ref="labelsBody" class="labels-body" aria-label="Assuntos" @scroll="syncLabels"><svg :width="labelWidth" :height="bodyHeight"><g v-for="({subject},index) in filteredRows" :key="subject.id" :transform="`translate(0 ${index*rowHeight})`"><rect width="100%" :height="rowHeight" fill="#f5faff" class="row"/><g v-if="subject.children.length" class="action" role="button" tabindex="0" :aria-label="`Alternar ${subject.name}`" @click="toggle(subject.id)" @keydown.enter.prevent="toggle(subject.id)"><text :x="14+subject.depth*18" y="31" class="chevron">{{ expanded[subject.id]===false?'›':'⌄' }}</text></g><rect :x="subjectIndent(subject)" y="20" width="9" height="9" rx="3" :fill="colorHex(subject.id)"/><text :x="subjectIndent(subject)+15" y="22" class="subject">{{ subject.name }}</text><text :x="subjectIndent(subject)+15" y="38" class="caption">{{ practiceDetail(subject) }}</text><text x="252" y="29" class="value">{{ estimateLabel(subject.id) }}</text><rect x="334" y="17" width="54" height="7" rx="4" fill="#dce8f5"/><rect x="334" y="17" :width="54*progress(subject)" height="7" rx="4" :fill="progressHex(subject)"/><text x="388" y="39" text-anchor="end" class="caption">{{ subject.accuracy===null?'Sem práticas':Math.round(subject.accuracy)+'%' }}</text></g></svg></div>
        <div ref="timelineBody" class="timeline-body" aria-label="Linha do tempo" @scroll="syncBody"><svg :width="timelineWidth" :height="bodyHeight"><g v-for="({subject},index) in filteredRows" :key="subject.id" :transform="`translate(0 ${index*rowHeight})`"><rect width="100%" :height="rowHeight" fill="#f5faff" class="row"/><line v-for="periodIndex in timeline.length+1" :key="periodIndex" :x1="(periodIndex-1)*periodWidth" y1="0" :x2="(periodIndex-1)*periodWidth" :y2="rowHeight" class="grid"/><g v-if="scheduleBySubject[subject.id]" class="action" role="button" tabindex="0" :aria-label="`Editar planejamento de ${subject.name}`" @click="openPlanner(subject.id)" @keydown.enter.prevent="openPlanner(subject.id)"><rect :x="bar(scheduleBySubject[subject.id]).x" y="15" :width="bar(scheduleBySubject[subject.id]).width" height="22" rx="4" :fill="colorHex(subject.id)" :opacity="scheduleBySubject[subject.id].status==='COMPLETED'?.68:1"/><text v-if="scheduleBySubject[subject.id].status!=='PLANNED'" :x="bar(scheduleBySubject[subject.id]).x+8" y="30" class="bar-label">✓ {{ scheduleBySubject[subject.id].status==='COMPLETED'?'Concluído':'Estudado' }}</text></g><g v-else class="action" role="button" tabindex="0" :aria-label="`Planejar ${subject.name}`" @click="openPlanner(subject.id)" @keydown.enter.prevent="openPlanner(subject.id)"><circle :cx="timelineWidth-17" cy="26" r="11" fill="#e1effd"/><text :x="timelineWidth-17" y="30" text-anchor="middle" class="add">+</text></g></g><g v-if="todayX!==null"><line :x1="todayX" y1="0" :x2="todayX" :y2="bodyHeight" class="today"/><text :x="todayX+4" y="12" class="today-label">Hoje</text></g></svg></div>
      </div></q-card-section></q-card></main>
      <aside class="insights"><q-card flat class="insight"><q-card-section><h3>Progresso geral <strong>{{ overallProgress }}%</strong></h3><q-linear-progress rounded size="10px" :value="overallProgress/100" color="positive"/><p>{{ completedCount }} de {{ map.schedule.length }} assuntos concluídos</p></q-card-section></q-card><q-card flat class="insight"><q-card-section><h3>Distribuição por disciplina</h3><div class="distribution"><div class="donut" :style="{background:donutGradient}"/><div class="donut-total"><strong>{{ map.schedule.length }}</strong><span>itens</span></div></div><div class="legend-list"><div v-for="item in distribution" :key="item.name"><span class="legend-dot" :class="item.color"/>{{ item.name }} <b>{{ item.count }} ({{ item.percent }}%)</b></div></div></q-card-section></q-card><q-card flat class="insight"><q-card-section><h3>Meus pontos fortes e fracos</h3><div v-if="insights.length" class="strengths"><div v-for="item in insights" :key="item.id"><div><span>{{ item.name }}</span><b>{{ item.accuracy }}%</b></div><q-linear-progress rounded size="8px" :value="item.accuracy/100" :color="item.accuracy>=70?'positive':item.accuracy>=50?'warning':'negative'"/></div></div><p v-else>Conclua práticas para ver seus indicadores.</p></q-card-section></q-card></aside></div>
    <q-btn class="add-activity" unelevated no-caps color="primary" icon="add" label="Adicionar atividade" @click="openPlanner()"/><q-dialog v-model="planner"><q-card class="planner"><q-card-section><div class="text-h6">Planejar assunto</div><div class="text-caption">A posição no calendário é preservada depois de estudado ou concluído.</div></q-card-section><q-card-section class="planner-form"><q-select v-model="form.subjectId" outlined dense emit-value map-options label="Assunto" :options="subjectOptions"/><q-input v-model="form.startDate" outlined dense type="date" label="Início"/><q-input v-model="form.endDate" outlined dense type="date" label="Fim"/><q-input v-model.number="form.estimatedMinutes" outlined dense type="number" min="0" label="Tempo estimado (minutos)"/><q-select v-model="form.status" outlined dense emit-value map-options label="Situação" :options="statusOptions"/><q-select v-model="form.predecessorSubjectIds" outlined dense multiple emit-value map-options label="Depende de" :options="predecessorOptions"/></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancelar" v-close-popup/><q-btn unelevated no-caps color="primary" label="Salvar" @click="save"/></q-card-actions></q-card></q-dialog>
  </section>
