<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import type {SaveStudyMapSchedule,StudyMap,StudyMapScheduleItem,StudyMapSubject} from '../../../Domain/Performance/PerformanceRepository'
const props=defineProps<{map:StudyMap}>(),emit=defineEmits<{save:[input:SaveStudyMapSchedule];periodChange:[from:string|null,to:string|null]}>();const labelWidth=405,headerHeight=44,rowHeight=52,search=ref(''),statusFilter=ref('ALL'),view=ref<'week'|'day'|'month'>('week'),expanded=reactive<Record<string,boolean>>({}),planner=ref(false),labelsBody=ref<HTMLElement|null>(null),timelineBody=ref<HTMLElement|null>(null),timelineHeader=ref<HTMLElement|null>(null)
const form=reactive<{subjectId:string;startDate:string;endDate:string;status:'PLANNED'|'STUDIED'|'COMPLETED';predecessorSubjectIds:string[];estimatedMinutes:number|null}>({subjectId:'',startDate:new Date().toISOString().slice(0,10),endDate:new Date(Date.now()+6*86400000).toISOString().slice(0,10),status:'PLANNED',predecessorSubjectIds:[],estimatedMinutes:null}),statusFilters=[{label:'Todas as situações',value:'ALL'},{label:'Planejados',value:'PLANNED'},{label:'Estudados',value:'STUDIED'},{label:'Concluídos',value:'COMPLETED'}],statusOptions=[{label:'Planejado',value:'PLANNED'},{label:'Estudado',value:'STUDIED'},{label:'Concluído',value:'COMPLETED'}] as const,palette=['blue','orange','green','purple','teal','pink','indigo','cyan'],colors:Record<string,string>={blue:'#398ee9',orange:'#ee9034',green:'#36ad7c',purple:'#9157df',teal:'#32afa7',pink:'#dc5e8e',indigo:'#5a70c9',cyan:'#41a9ca'}
const scheduleBySubject=computed<Record<string,StudyMapScheduleItem>>(()=>Object.fromEntries(props.map.schedule.map(x=>[x.subjectId,x])));function hasScheduled(s:StudyMapSubject):boolean{return!!scheduleBySubject.value[s.id]||s.children.some(hasScheduled)}function collect(nodes:readonly StudyMapSubject[],out:{subject:StudyMapSubject}[]=[]):{subject:StudyMapSubject}[]{for(const subject of nodes)if(hasScheduled(subject)){out.push({subject});if(expanded[subject.id]!==false)collect(subject.children,out)}return out}const rows=computed(()=>collect(props.map.subjects)),filteredRows=computed(()=>rows.value.filter(({subject})=>{const x=scheduleBySubject.value[subject.id];return(!search.value||subject.name.toLocaleLowerCase().includes(search.value.toLocaleLowerCase()))&&(statusFilter.value==='ALL'||x?.status===statusFilter.value)})),allSubjects=computed(()=>{const out:StudyMapSubject[]=[];const walk=(nodes:readonly StudyMapSubject[])=>nodes.forEach(x=>{out.push(x);walk(x.children)});walk(props.map.subjects);return out}),subjectOptions=computed(()=>allSubjects.value.map(x=>({label:'  '.repeat(x.depth)+x.name,value:x.id}))),predecessorOptions=computed(()=>allSubjects.value.filter(x=>x.id!==form.subjectId&&scheduleBySubject.value[x.id]).map(x=>({label:x.name,value:x.id})))
const completedCount=computed(()=>props.map.schedule.filter(x=>x.status==='COMPLETED').length),overallProgress=computed(()=>props.map.schedule.length?Math.round(completedCount.value/props.map.schedule.length*100):0),accuracyLabel=computed(()=>props.map.accuracy===null?'Sem dados':Math.round(props.map.accuracy)+'%'),totalEstimated=computed<number|null>(()=>props.map.schedule.some(x=>x.estimatedMinutes===null)?null:props.map.schedule.reduce((n,x)=>n+(x.estimatedMinutes??0),0)),remainingEstimated=computed<number|null>(()=>totalEstimated.value===null?null:totalEstimated.value-props.map.schedule.filter(x=>x.status==='COMPLETED').reduce((n,x)=>n+(x.estimatedMinutes??0),0))
const timeline=computed(()=>Array.from({length:8},(_,i)=>{const start=props.map.schedule.map(x=>x.startDate).sort()[0]??new Date().toISOString().slice(0,10),d=new Date(start+'T12:00:00');view.value==='month'?d.setMonth(d.getMonth()+i):d.setDate(d.getDate()+i*(view.value==='week'?7:1));return d.toISOString().slice(0,10)})),periodWidth=computed(()=>view.value==='day'?110:view.value==='month'?145:130),timelineWidth=computed(()=>timeline.value.length*periodWidth.value),bodyHeight=computed(()=>Math.max(filteredRows.value.length*rowHeight,rowHeight)),todayX=computed<number|null>(()=>{const start=new Date(timeline.value[0]+'T12:00:00'),now=new Date(),offset=view.value==='month'?(now.getFullYear()-start.getFullYear())*12+now.getMonth()-start.getMonth():Math.floor((now.getTime()-start.getTime())/86400000/(view.value==='week'?7:1));return offset>=0&&offset<timeline.value.length?offset*periodWidth.value:null})
const distribution=computed(()=>{const c=new Map<string,number>();for(const {subject} of rows.value)if(scheduleBySubject.value[subject.id])c.set(subject.name,(c.get(subject.name)??0)+1);const total=props.map.schedule.length||1;return[...c].map(([name,count],i)=>({name,count,percent:Math.round(count/total*100),color:palette[i%palette.length]}))}),donutGradient=computed(()=>{let n=0;return`conic-gradient(${distribution.value.map(x=>{const end=n+x.percent,v=`var(--q-${x.color}) ${n}% ${end}%`;n=end;return v}).join(',')||'#dbe7f5 0 100%'})`}),insights=computed(()=>rows.value.map(({subject})=>({id:subject.id,name:subject.name,accuracy:subject.accuracy})).filter((x):x is {id:string;name:string;accuracy:number}=>x.accuracy!==null).sort((a,b)=>b.accuracy-a.accuracy).slice(0,8))
function syncLabels(e:Event){if(timelineBody.value)timelineBody.value.scrollTop=(e.currentTarget as HTMLElement).scrollTop}function syncBody(e:Event){const x=e.currentTarget as HTMLElement;if(labelsBody.value)labelsBody.value.scrollTop=x.scrollTop;if(timelineHeader.value)timelineHeader.value.scrollLeft=x.scrollLeft}function syncHeader(e:Event){if(timelineBody.value)timelineBody.value.scrollLeft=(e.currentTarget as HTMLElement).scrollLeft}function toggle(id:string){expanded[id]=expanded[id]===false}function expandAll(){for(const x of allSubjects.value)expanded[x.id]=true}function collapseAll(){for(const x of allSubjects.value)if(x.children.length)expanded[x.id]=false}function openPlanner(id?:string){const x=id?scheduleBySubject.value[id]:undefined;form.subjectId=id??form.subjectId;form.startDate=x?.startDate??form.startDate;form.endDate=x?.endDate??form.endDate;form.status=x?.status??'PLANNED';form.predecessorSubjectIds=[...(x?.predecessorSubjectIds??[])];form.estimatedMinutes=x?.estimatedMinutes??null;planner.value=true}function save(){if(!form.subjectId)return;emit('save',{examId:props.map.examId,subjectId:form.subjectId,startDate:form.startDate,endDate:form.endDate,status:form.status,predecessorSubjectIds:form.predecessorSubjectIds,estimatedMinutes:form.estimatedMinutes});planner.value=false}function timelineLabel(d:string){return new Intl.DateTimeFormat('pt-BR',view.value==='month'?{month:'short',year:'2-digit'}:{day:'2-digit',month:'2-digit'}).format(new Date(d+'T12:00:00'))}function colorClass(id:string){return palette[Math.abs([...id].reduce((n,x)=>n+x.charCodeAt(0),0))%palette.length]}function colorHex(id:string){return colors[colorClass(id)]}function subjectIndent(x:StudyMapSubject){return 16+x.depth*18+(x.children.length?17:0)}function progress(x:StudyMapSubject){return(x.accuracy??0)/100}function progressHex(x:StudyMapSubject){return x.accuracy===null?'#b8c8d9':x.accuracy>=70?'#36ad7c':x.accuracy>=50?'#ee9034':'#e25955'}function practiceDetail(x:StudyMapSubject){return x.accuracy===null?'Sem práticas':`${x.correct}/${x.answered} acertos`}function estimateLabel(id:string){const n=scheduleBySubject.value[id]?.estimatedMinutes;return n===null||n===undefined?(scheduleBySubject.value[id]?'Não informado':'—'):minutesLabel(n)}function minutesLabel(n:number){return n%60===0?`${n/60} h`:`${Math.floor(n/60)} h ${n%60} min`}function bar(x:StudyMapScheduleItem){const s=new Date(timeline.value[0]+'T12:00:00'),a=new Date(x.startDate+'T12:00:00'),b=new Date(x.endDate+'T12:00:00'),d=86400000,o=Math.max(0,view.value==='month'?(a.getFullYear()-s.getFullYear())*12+a.getMonth()-s.getMonth():(a.getTime()-s.getTime())/d/(view.value==='week'?7:1)),l=Math.max(1,view.value==='month'?(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth()+1:(b.getTime()-a.getTime())/d/(view.value==='week'?7:1)+1);return{x:o*periodWidth.value,width:Math.max(16,Math.min(timelineWidth.value-o*periodWidth.value,l*periodWidth.value))}}
</script>
